class Solution:
    def checkPerfectNumber(self, num: int) -> bool:
        if num <= 1:
            return False
        sum_divisors = 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                sum_divisors += i
                if i != num // i:
                    sum_divisors += num // i
        return sum_divisors == num

class Solution:
    def binaryGap(self, n: int) -> int:
        max_gap = 0
        current_gap = 0
        found_one = False
        while n > 0:
            if n % 2 == 1:
                if found_one:
                    max_gap = max(max_gap, current_gap)
                current_gap = 1
                found_one = True
            elif found_one:
                current_gap += 1
            n //= 2
        return max_gap

class Solution:
    def findNthDigit(self, n: int) -> int:
        if n < 10:
            return n
        digit = 1
        while True:
            start = 10 ** (digit - 1)
            end = start * 10 - 1
            total_digits = (end - start + 1) * digit
            if n <= total_digits:
                break
            n -= total_digits
            digit += 1
        num = start + (n - 1) // digit
        return int(str(num)[(n - 1) % digit])

from functools import reduce

def berserk_rater(synopsis):
    def update_score(score, event):
        event = event.lower()
        if 'cg' in event:
            score -= 2
        elif 'clang' in event:
            score += 5
        elif score >= 0:
            score -= 1
        return score

    final_score = reduce(update_score, synopsis, 0)
    if final_score < 0:
        return 'worstest episode ever'
    elif final_score <= 10:
        return str(final_score)
    else:
        return 'bestest episode ever'

def harmonic_sum(n):
    if n < 2:
        return 1
    else:
        return 1 / n + harmonic_sum(n - 1)

