def pow_root_pandigit(val, n, k):
    def is_pandigital(num):
        s = str(num)
        return len(s) == len(set(s)) and '0' not in s

    result = []
    i = int(val ** (1/n)) + 1
    while len(result) < k:
        candidate = i ** n
        if candidate <= val:
            i += 1
            continue
        root = i
        if is_pandigital(root) and is_pandigital(candidate):
            result.append([root, candidate])
        i += 1
    return result if len(result) > 1 else result[0]

def remove_rotten(bag_of_fruits):
    if not bag_of_fruits:
        return []
    return [fruit.lower() if 'rotten' in fruit else fruit.lower() for fruit in bag_of_fruits]

def reverse_fun(n):
    n = list(n)
    for i in range(len(n)):
        n[i:] = n[:i+1][::-1]
    return ''.join(n)

def fizz_buzz_cuckoo_clock(time):
    h, m = map(int, time.split(':'))
    h %= 12
    if m == 0:
        return 'Cuckoo ' * h + ('Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo' if h == 0 else '')
    elif m == 30:
        return 'Cuckoo'
    elif m % 3 == 0 and m % 5 == 0:
        return 'Fizz Buzz'
    elif m % 3 == 0:
        return 'Fizz'
    elif m % 5 == 0:
        return 'Buzz'
    else:
        return 'tick'

def find_extra_element_index(arr1, arr2):
    if len(arr1) > len(arr2):
        return next(i for i, (x, y) in enumerate(zip(arr1, arr2)) if x != y)
    else:
        return next(i for i, (y, x) in enumerate(zip(arr2, arr1)) if y != x)

