def max_product_pair(arr):
    arr.sort()
    n = len(arr)
    return max(arr[0] * arr[1], arr[n - 1] * arr[n - 2])

def diff_even_odd(lst):
    even = None
    odd = None
    for num in lst:
        if num % 2 == 0:
            if even is None:
                even = num
            else:
                even = min(even, num)
        else:
            if odd is None:
                odd = num
            else:
                odd = max(odd, num)
    return even - odd
